describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 10000 = 1000, plus fixed 200 = 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("each policy receives original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "sum",
      );
      // both get 10000 → 5000 + 5000 = 10000
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("can exceed subtotal (clamping is caller's responsibility)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(6000), new FixedAmountDiscountPolicy(6000)],
        "sum",
      );
      // Both cap at subtotal individually: min(6000,10000)=6000 each → 12000
      // But FixedAmount caps at subtotal so each returns min(6000, 10000) = 6000
      expect(composite.computeDiscountCents(10000)).toBe(12000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // 10% of 10000 = 1000, remaining = 9000; fixed 200 off 9000 = 200; total = 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("order matters in chain mode", () => {
      const p10 = new PercentageDiscountPolicy(10);
      const p50 = new PercentageDiscountPolicy(50);

      const first = new CompositeDiscountPolicy([p10, p50], "chain");
      const second = new CompositeDiscountPolicy([p50, p10], "chain");

      // [10%, 50%]: 10% of 1000 = 100, remaining 900; 50% of 900 = 450; total = 550
      expect(first.computeDiscountCents(1000)).toBe(550);
      // [50%, 10%]: 50% of 1000 = 500, remaining 500; 10% of 500 = 50; total = 550
      expect(second.computeDiscountCents(1000)).toBe(550);
    });

    it("chain cannot exceed subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(8000), new FixedAmountDiscountPolicy(8000)],
        "chain",
      );
      // first: min(8000, 10000)=8000, remaining=2000; second: min(8000, 2000)=2000; total=10000
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

