        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1000 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 2)]; // no weightGrams
      expect(calc.computeShippingCents(lines, 2000)).toBe(0);
    });

    it("selects first bracket (weight exactly at boundary)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 500)]; // 500g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects first bracket (weight below boundary)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 200)]; // 200g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects second bracket (weight just above first boundary)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 501)]; // 501g
      expect(calc.computeShippingCents(lines, 1000)).toBe(500);
    });

    it("selects second bracket (weight exactly at second boundary)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 1000)]; // 1000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(500);
    });

    it("selects third bracket", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 3000)]; // 3000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(1000);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = [makeLine("a", 1000, 1, 6000)]; // 6000g > 5000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("defaults overflow to heaviest bracket cost", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 10000)]; // 10000g > 5000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(1000);
    });

    it("sums weight across multiple lines (quantity considered)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [
        makeLine("a", 1000, 2, 300), // 300*2 = 600g
        makeLine("b", 500, 1, 200),  // 200*1 = 200g → total 800g
      ];
      expect(calc.computeShippingCents(lines, 2500)).toBe(500); // 800g → second bracket
    });

    it("sorts brackets by upToGrams regardless of input order", () => {
      const unordered = [
        { upToGrams: 5000, costCents: 1000 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      const lines = [makeLine("a", 1000, 1, 400)]; // 400g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (
  id: string,
  unitPriceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  weightGrams,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(cart.itemCount).toBe(1);
    });

    it("merges quantity when adding the same product again", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("a", 1000), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("throws on zero quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
    });

    it("throws on negative quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
    });

    it("throws on non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
    });

    it("throws on negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws on negative quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("throws on non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });

    it("throws for product not in cart", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("itemCount", () => {
    it("is 0 for empty cart", () => {
      const cart = new Cart();
      expect(cart.itemCount).toBe(0);
    });

    it("sums quantities across all lines", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      cart.add(product("b", 200), 3);
      expect(cart.itemCount).toBe(5);
    });
  });

  describe("snapshot", () => {
    it("returns deep copy of lines", () => {
      const cart = new Cart();
      const p = product("a", 1000);
      cart.add(p, 2);
      const snap = cart.snapshot();
      // Mutate snapshot and verify cart is unaffected
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 500), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3500); // 2000 + 1500
    });

    it("applies discount policy", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product("a", 2000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500);
      expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(2000);
    });

    it("clamps discount to [0, subtotal]", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product("a", 1000), 1);
