import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (id: string, unitPriceCents: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
});

describe("Cart.checkout()", () => {
  describe("without collaborators", () => {
    it("returns totals and lines for a populated cart", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.quantity).toBe(2);
    });

    it("returns zero totals for empty cart", async () => {
      const cart = new Cart();
      const result = await cart.checkout();
      expect(result.totals.totalCents).toBe(0);
      expect(result.lines).toHaveLength(0);
    });
  });

  describe("with priceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(result.totals.subtotalCents).toBe(1500);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("refreshes prices for multiple products", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation((id: string) =>
          id === "a" ? Promise.resolve(1100) : Promise.resolve(2200),
        ),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(1100 + 2200 * 2); // 5500
    });

    it("throws RangeError when fetcher returns invalid price", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates fetcher rejection", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("service down");
    });
  });

  describe("with inventoryChecker", () => {
    it("passes when all items are available", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
          reason: "out of stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(2);
        expect(err.available).toBe(0);
        expect(err.message).toBe("out of stock");
      }
    });

    it("throws InventoryError on partial-stock denial (availableQuantity < requested)", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(3);
      }
    });

    it("InventoryError has correct name", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        expect((e as InventoryError).name).toBe("InventoryError");
      }
    });

    it("first denial wins when multiple items fail", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 1);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockImplementation((id: string) => {
          if (id === "a") return Promise.resolve({ available: false, reason: "a unavailable" });
          return Promise.resolve({ available: false, reason: "b unavailable" });
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        // First item checked should fail first
        expect((e as InventoryError).productId).toBe("a");
      }
    });
  });

  describe("with asyncTaxProvider", () => {
    it("uses async tax provider for tax computation", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(product("a", 10000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      // 8.75% of 10000 = 875
      expect(result.totals.taxCents).toBe(875);
    });

    it("applies discount before async tax", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(2000),
      };
      const cart = new Cart({ discountPolicy, region: "US" });
      cart.add(product("a", 10000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=10000, discount=2000, taxable=8000, tax=800
      expect(result.totals.taxCents).toBe(800);
    });

    it("propagates async tax provider failure", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "rate service down",
      );
    });

    it("throws RangeError for invalid async tax rate", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(2.0),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(RangeError);
    });
  });

  describe("full pipeline with all collaborators", () => {
    it("price refresh → inventory check → async tax + discount + shipping", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(599),
      };
      const cart = new Cart({ discountPolicy, shippingCalculator, region: "FR" });
      cart.add(product("a", 500), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(600),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Price refreshed to 600, qty 2 → subtotal = 1200
      expect(result.totals.subtotalCents).toBe(1200);
      // Discount = 100 → discounted = 1100
      expect(result.totals.discountCents).toBe(100);
      // Tax = 20% of 1100 = 220
      expect(result.totals.taxCents).toBe(220);
      // Shipping = 599
      expect(result.totals.shippingCents).toBe(599);
      // Total = 1100 + 220 + 599 = 1919
      expect(result.totals.totalCents).toBe(1919);

      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { refreshPrices, InventoryError } from "../src/inventory.ts";
import type { PriceFetcher } from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("refreshPrices", () => {
  const makeLine = (id: string, price: number, qty: number): CartLine => ({
    product: { id, name: id, unitPriceCents: price },
    quantity: qty,
  });

  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation((id: string) =>
        id === "a" ? Promise.resolve(1500) : Promise.resolve(2500),
      ),
    };
    const lines = [makeLine("a", 1000, 1), makeLine("b", 2000, 2)];
    const result = await refreshPrices(lines, fetcher);

    expect(result[0]!.product.unitPriceCents).toBe(1500);
    expect(result[1]!.product.unitPriceCents).toBe(2500);
    expect(result[0]!.quantity).toBe(1);
    expect(result[1]!.quantity).toBe(2);
  });

  it("preserves other product properties", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const lines: CartLine[] = [
      {
        product: { id: "x", name: "Widget", unitPriceCents: 500, weightGrams: 100, currency: "EUR" },
        quantity: 3,
      },
    ];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.name).toBe("Widget");
    expect(result[0]!.product.weightGrams).toBe(100);
    expect(result[0]!.product.currency).toBe("EUR");
    expect(result[0]!.product.unitPriceCents).toBe(999);
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    const lines = [makeLine("a", 1000, 1)];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    const lines = [makeLine("a", 1000, 1)];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(NaN),
    };
    const lines = [makeLine("a", 1000, 1)];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("timeout")),
    };
    const lines = [makeLine("a", 1000, 1)];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("timeout");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("accepts price of 0", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(0),
    };
    const lines = [makeLine("a", 1000, 1)];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.unitPriceCents).toBe(0);
  });
});

