      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 1000)).toBe(599);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
