import { describe, it, expect, vi } from "vitest";
import { refreshPrices, InventoryError } from "../src/inventory.ts";
import type { PriceFetcher } from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("refreshPrices", () => {
  const makeLine = (id: string, price: number, qty: number): CartLine => ({
    product: { id, name: id, unitPriceCents: price },
    quantity: qty,
  });

  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation((id: string) =>
        id === "a" ? Promise.resolve(1500) : Promise.resolve(2500),
      ),
    };
    const lines = [makeLine("a", 1000, 1), makeLine("b", 2000, 2)];
    const result = await refreshPrices(lines, fetcher);

    expect(result[0]!.product.unitPriceCents).toBe(1500);
    expect(result[1]!.product.unitPriceCents).toBe(2500);
    expect(result[0]!.quantity).toBe(1);
    expect(result[1]!.quantity).toBe(2);
  });

  it("preserves other product properties", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const lines: CartLine[] = [
      {
        product: { id: "x", name: "Widget", unitPriceCents: 500, weightGrams: 100, currency: "EUR" },
        quantity: 3,
      },
    ];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.name).toBe("Widget");
    expect(result[0]!.product.weightGrams).toBe(100);
    expect(result[0]!.product.currency).toBe("EUR");
    expect(result[0]!.product.unitPriceCents).toBe(999);
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    const lines = [makeLine("a", 1000, 1)];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    const lines = [makeLine("a", 1000, 1)];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(NaN),
    };
    const lines = [makeLine("a", 1000, 1)];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("timeout")),
    };
    const lines = [makeLine("a", 1000, 1)];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("timeout");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("accepts price of 0", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(0),
    };
    const lines = [makeLine("a", 1000, 1)];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.unitPriceCents).toBe(0);
  });
});

describe("InventoryError", () => {
  it("has correct properties", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
