toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  unitPriceCents: number,
  quantity: number,
  weightGrams?: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 1000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 100.5)).toThrow(RangeError);
    });

    it("accepts 0 flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts valid flatCents and freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 5000)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([], 10000)).toBe(0);
    });

    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 1000)).toBe(599);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 6000, 1)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 4999, 1)], 4999)).toBe(500);
    });

    it("no free-over threshold means always charges flat", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([makeLine("a", 100000, 1)], 100000)).toBe(500);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1000 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 2)]; // no weightGrams
      expect(calc.computeShippingCents(lines, 2000)).toBe(0);
    });

    it("selects first bracket (weight exactly at boundary)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 500)]; // 500g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects first bracket (weight below boundary)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 200)]; // 200g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects second bracket (weight just above first boundary)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 501)]; // 501g
      expect(calc.computeShippingCents(lines, 1000)).toBe(500);
    });

    it("selects second bracket (weight exactly at second boundary)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 1000)]; // 1000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(500);
    });

    it("selects third bracket", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 3000)]; // 3000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(1000);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = [makeLine("a", 1000, 1, 6000)]; // 6000g > 5000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("defaults overflow to heaviest bracket cost", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 10000)]; // 10000g > 5000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(1000);
    });

    it("sums weight across multiple lines (quantity considered)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [
        makeLine("a", 1000, 2, 300), // 300*2 = 600g
        makeLine("b", 500, 1, 200),  // 200*1 = 200g → total 800g
      ];
      expect(calc.computeShippingCents(lines, 2500)).toBe(500); // 800g → second bracket
    });

    it("sorts brackets by upToGrams regardless of input order", () => {
      const unordered = [
        { upToGrams: 5000, costCents: 1000 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      const lines = [makeLine("a", 1000, 1, 400)]; // 400g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });
  });
});

